import{_ as n,C as i,c as l,o as g,a3 as r,G as s,j as a,a as e}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Storage categories","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/warehouses/storage-categories.md","filePath":"master/supply-chain/inventories/warehouses/storage-categories.md","lastUpdated":1793074831000}'),c={name:"master/supply-chain/inventories/warehouses/storage-categories.md"};function h(d,t,p,u,y,m){const o=i("ImagePopup");return g(),l("div",null,[t[0]||(t[0]=r('<h1 id="storage-categories" tabindex="-1">Storage categories <a class="header-anchor" href="#storage-categories" aria-label="Permalink to &quot;Storage categories&quot;">​</a></h1><p>A storage category describes how much a kind of shelf can hold. You attach it to locations, and the system then knows the weight limit and the capacity for packages or products. Use it when your racks, bins or pallet positions have real limits.</p><blockquote><p><strong>In simple words:</strong> A storage category is a label that says &quot;this shelf holds at most this much&quot;, which you stick on one or many locations.</p></blockquote><p>Open <code>Inventory → Configurations → Warehouse Management → Storage Categories</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The menu appears when <strong>Multi Steps Routes</strong> is on in <code>Inventory → Settings → Manage Warehouses</code>. To set capacity by package type, also turn on <strong>Packages</strong> in <code>Inventory → Settings → Manage Operations</code>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows <strong>Name</strong>, <strong>Allow New Products</strong>, <strong>Max Weight</strong> and <strong>Company</strong>. You can group by <strong>Allow New Products</strong>. A new database starts with no categories.</p>',8)),s(o,{src:"/images1/inventory/wh_storage_category_list.png",alt:"Storage Categories list with Pallet Rack row showing Mixed and max weight 500"}),t[1]||(t[1]=a("h2",{id:"create-a-storage-category",tabindex:"-1"},[e("Create a storage category "),a("a",{class:"header-anchor",href:"#create-a-storage-category","aria-label":'Permalink to "Create a storage category"'},"​")],-1)),t[2]||(t[2]=a("ol",null,[a("li",null,[e("Click "),a("strong",null,"New Storage Category"),e(".")]),a("li",null,"Fill the form."),a("li",null,[e("Click "),a("strong",null,"Create"),e(".")])],-1)),s(o,{src:"/images1/inventory/wh_storage_category_create.png",alt:"Create Storage Category form with name Pallet Rack, max weight 500 and Allow New Products Mixed"}),t[3]||(t[3]=r('<ul><li><strong><em>Name:</em></strong> For example <strong>Pallet Rack</strong>. Required.</li><li><strong><em>Max Weight:</em></strong> The most weight a location of this category may hold. The default is 0.</li><li><strong><em>Allow New Products:</em></strong> Required. Choose <strong>Empty</strong>, <strong>Same</strong> or <strong>Mixed</strong>. The default is <strong>Mixed</strong>.</li><li><strong><em>Company:</em></strong> Your current company by default.</li></ul><h3 id="what-allow-new-products-means" tabindex="-1">What Allow New Products means <a class="header-anchor" href="#what-allow-new-products-means" aria-label="Permalink to &quot;What Allow New Products means&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Empty</strong></td><td>Put new products here only when the location is empty.</td></tr><tr><td><strong>Same</strong></td><td>Put new products here only when it already holds the same product.</td></tr><tr><td><strong>Mixed</strong></td><td>Put any product here.</td></tr></tbody></table><h2 id="capacity-tabs" tabindex="-1">Capacity tabs <a class="header-anchor" href="#capacity-tabs" aria-label="Permalink to &quot;Capacity tabs&quot;">​</a></h2><p>After you save, open the record. The top of the page has the tabs <strong>View</strong>, <strong>Edit</strong>, <strong>Capacity By Packages</strong>, <strong>Capacity By Products</strong> and <strong>Locations</strong>. The <strong>View</strong> tab is read only. Each capacity tab opens its own page where you add and change rows.</p><h3 id="capacity-by-packages" tabindex="-1">Capacity by packages <a class="header-anchor" href="#capacity-by-packages" aria-label="Permalink to &quot;Capacity by packages&quot;">​</a></h3><ol><li>Open the <strong>Capacity By Packages</strong> tab.</li><li>Click <strong>Add Package Type Capacity</strong>. The <strong>Create Storage Category Capacity</strong> window opens.</li><li>Choose the <strong>Package Type</strong> and enter the <strong>Quantity</strong>. Both are required.</li><li>Click <strong>Create</strong>. The row is saved at once.</li></ol><p>Each row has <strong>Edit</strong> and <strong>Delete</strong> links.</p><p>Example: a pallet rack holds 4 <strong>Pallet</strong> packages.</p><h3 id="capacity-by-products" tabindex="-1">Capacity by products <a class="header-anchor" href="#capacity-by-products" aria-label="Permalink to &quot;Capacity by products&quot;">​</a></h3><ol><li>Open the <strong>Capacity By Products</strong> tab.</li><li>Click <strong>Add Product Capacity</strong>. The <strong>Create Storage Category Capacity</strong> window opens.</li><li>Choose the <strong>Product</strong> and enter the <strong>Quantity</strong>. Both are required.</li><li>Click <strong>Create</strong>. The row is saved at once.</li></ol><p>Each row has <strong>Edit</strong> and <strong>Delete</strong> links.</p><p>Example: a bin holds at most 40 <strong>Vitamin C Tablets 500mg</strong>.</p>',13)),s(o,{src:"/images1/inventory/wh_storage_category_capacity.png",alt:"Capacity By Products page listing Vitamin C Tablets 500mg with quantity 40"}),t[4]||(t[4]=r('<h3 id="locations-tab" tabindex="-1">Locations tab <a class="header-anchor" href="#locations-tab" aria-label="Permalink to &quot;Locations tab&quot;">​</a></h3><p>The <strong>Locations</strong> tab lists the locations that use this category. Click <strong>Create Location</strong> to add one with the category already set. You can also pick the category on any internal location. See <a href="./locations.html">Locations</a>.</p><h2 id="use-it-with-putaway-rules" tabindex="-1">Use it with putaway rules <a class="header-anchor" href="#use-it-with-putaway-rules" aria-label="Permalink to &quot;Use it with putaway rules&quot;">​</a></h2><p>A putaway rule can name a storage category. When goods arrive, the system sends them to a location of that category. See <a href="./../routes/putaway-rules.html">Putaway rules</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Start with weight only. Add package or product capacity once the basic flow works.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./locations.html">Locations</a></li><li><a href="./../routes/putaway-rules.html">Putaway rules</a></li><li><a href="./../tracking/packages.html">Packages</a></li></ul>',7))])}const C=n(c,[["render",h]]);export{b as __pageData,C as default};
